private void registerCommands(){
  handler.register("help","","Displays this command list.",arg -> {
    info("Commands:");
    for (    Command command : handler.getCommandList()) {
      print("   &y" + command.text + (command.params.isEmpty() ? "" : " ")+ command.params+ " - &lm"+ command.description);
    }
  }
);
  handler.register("exit","","Exit the server application.",arg -> {
    info("Shutting down server.");
    Net.dispose();
    Gdx.app.exit();
  }
);
  handler.register("stop","","Stop hosting the server.",arg -> {
    Net.closeServer();
    state.set(State.menu);
  }
);
  handler.register("host","<mapname>","Open the server with a specific map.",arg -> {
    try {
      if (state.is(State.playing)) {
        err("Already hosting. Type 'stop' to stop hosting first.");
      }
      String search=arg[0];
      Map result=null;
      for (    Map map : world.maps().list()) {
        if (map.name.equalsIgnoreCase(search))       result=map;
      }
      if (result == null) {
        err("No map with name &y'{0}'&lg found.",search);
        return;
      }
      info("Loading map...");
      logic.reset();
      world.loadMap(result);
      state.set(State.playing);
      info("Map loaded.");
      Net.host(port);
      info("Server opened.");
    } catch (Exception e) {
      UCore.error(e);
    }
  }
);
}
